            const cardBlock = new YMap();
            cardBlock.set("sys:id", cardId);
            cardBlock.set("sys:flavour", "affine:paragraph");
            cardBlock.set("sys:version", 1);
            cardBlock.set("sys:parent", databaseBlockId);
