            sourceWorkspaceId: stringType().optional().describe("Source workspace ID (omit for same-workspace)"),
            removeFromSource: booleanType().optional().describe("Remove from source after move (default true)"),
            onBlobError: enumType(["abort", "skip"]).optional().describe("Blob error handling: abort (default) or skip"),
            preserveFolderStructure: booleanType().optional().describe("Recreate source subfolder structure under targetFolderId (default false)"),
